// Engine test for "life": "auto" (engine/shared/life-auto.mjs, 7 Nov 2026): an existing clip with nothing changed
// but its set's life, on a calm day and in a storm, to show what every new clip on a painted outdoor set gets.
//   node storyboards/env/make-life-auto-tests.mjs -> storyboards/env/life-auto-tent.json + life-auto-tent-storm.json
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const OUT = path.dirname(fileURLToPath(import.meta.url));
const SRC = path.join(OUT, "../series/friends-try-to/02-pitch-a-tent/pitch-a-tent.json");
for (const [id, life] of [["life-auto-tent", "auto"], ["life-auto-tent-storm", "storm"]]) {
  const sb = JSON.parse(fs.readFileSync(SRC, "utf8"));
  Object.assign(sb, { id, title: `${sb.title} (engine test: life ${life})`, notes: "Generated by storyboards/env/make-life-auto-tests.mjs from pitch-a-tent.json." });
  sb.set = { ...sb.set, life };
  fs.writeFileSync(path.join(OUT, `${id}.json`), JSON.stringify(sb, null, 1) + "\n");
  console.log(`wrote storyboards/env/${id}.json`);
}
